def action_for(qtarget, stance=True):
 p=np.zeros(m.nu)
 for i in range(21):
  jid=int(m.actuator_trnid[i,0]); adr=int(m.jnt_qposadr[jid]); p[i]=qtarget[adr]
 if stance:
  p[1],p[6]=.054,-.054;p[2],p[7]=-.044,-.044;p[3],p[8]=.545,.545;p[4],p[9]=-.381,-.381;p[10]=-.437
 for i in range(21,m.nu):
  nm=m.actuator(i).name
  if m.actuator_trntype[i]==3:
   hand='lh' if nm.startswith('lh') else 'rh'; f=nm.split('_A_')[1][0:2]
   p[i]=qtarget[m.joint(hand+'_'+f+'J2').id and int(m.jnt_qposadr[m.joint(hand+'_'+f+'J2').id])] + qtarget[int(m.jnt_qposadr[m.joint(hand+'_'+f+'J1').id])]
  else:
   jid=int(m.actuator_trnid[i,0]);adr=int(m.jnt_qposadr[jid]);p[i]=qtarget[adr]
 lo=m.actuator_ctrlrange[:,0];hi=m.actuator_ctrlrange[:,1]
 return np.clip(2*(p-lo)/(hi-lo)-1,-1,1)

